import{_ as a,c as t,o as i,ae as s}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"Configuring User Preferences in Sairis","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-preferences.md","filePath":"Administration/Manage/Users/user-preferences.md"}'),n={name:"Administration/Manage/Users/user-preferences.md"};function r(l,e,o,c,u,h){return i(),t("div",null,e[0]||(e[0]=[s('<h1 id="configuring-user-preferences-in-sairis" tabindex="-1">Configuring User Preferences in Sairis <a class="header-anchor" href="#configuring-user-preferences-in-sairis" aria-label="Permalink to &quot;Configuring User Preferences in Sairis&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>Learn how to customize user preferences, manage application access, and configure individual settings for users in the Sairis platform. This guide will walk you through the various options available in the Preferences tab of a user&#39;s profile.</p><h2 id="accessing-user-preferences" tabindex="-1">Accessing User Preferences <a class="header-anchor" href="#accessing-user-preferences" aria-label="Permalink to &quot;Accessing User Preferences&quot;">​</a></h2><ol><li>Navigate to the Users section in the Manage menu.</li><li>Select a specific user profile.</li><li>Click on the <strong>Preferences</strong> tab.</li></ol><h2 id="language-and-interface-settings" tabindex="-1">Language and Interface Settings <a class="header-anchor" href="#language-and-interface-settings" aria-label="Permalink to &quot;Language and Interface Settings&quot;">​</a></h2><h3 id="language-selection" tabindex="-1">Language Selection <a class="header-anchor" href="#language-selection" aria-label="Permalink to &quot;Language Selection&quot;">​</a></h3><ul><li>Choose the primary language for the user&#39;s interface.</li><li>Available options include: <ul><li>English (default)</li><li>Spanish</li><li>French</li></ul></li></ul><h3 id="default-ai-assistant-blueprint" tabindex="-1">Default AI Assistant Blueprint <a class="header-anchor" href="#default-ai-assistant-blueprint" aria-label="Permalink to &quot;Default AI Assistant Blueprint&quot;">​</a></h3><ul><li>Select a default Blueprint that will load when the user starts an Assistant session.</li><li>Optional setting can be left blank.</li></ul><h2 id="login-and-session-preferences" tabindex="-1">Login and Session Preferences <a class="header-anchor" href="#login-and-session-preferences" aria-label="Permalink to &quot;Login and Session Preferences&quot;">​</a></h2><h3 id="auto-login-remember-me" tabindex="-1">Auto Login (Remember Me) <a class="header-anchor" href="#auto-login-remember-me" aria-label="Permalink to &quot;Auto Login (Remember Me)&quot;">​</a></h3><ul><li>Toggle the Auto Login feature on or off.</li><li>When enabled, the user&#39;s login credentials will be remembered.</li></ul><h3 id="control-panel-display" tabindex="-1">Control Panel Display <a class="header-anchor" href="#control-panel-display" aria-label="Permalink to &quot;Control Panel Display&quot;">​</a></h3><ul><li>Choose whether the Assistant Control Panel starts expanded or collapsed by default.</li></ul><h3 id="session-timeout" tabindex="-1">Session Timeout <a class="header-anchor" href="#session-timeout" aria-label="Permalink to &quot;Session Timeout&quot;">​</a></h3><ul><li>Set the duration after which the user will be automatically logged out.</li><li>Available options: <ul><li>0 minutes (no timeout)</li><li>30 minutes</li><li>1 hour</li><li>4 hours</li><li>8 hours</li><li>12 hours</li><li>24 hours</li></ul></li></ul><h2 id="theme-preferences" tabindex="-1">Theme Preferences <a class="header-anchor" href="#theme-preferences" aria-label="Permalink to &quot;Theme Preferences&quot;">​</a></h2><ul><li>Select the interface theme: <ul><li>Light mode</li><li>Dark mode</li></ul></li></ul><h2 id="user-application-modules" tabindex="-1">User Application Modules <a class="header-anchor" href="#user-application-modules" aria-label="Permalink to &quot;User Application Modules&quot;">​</a></h2><p>Configure which application modules the user can access:</p><h3 id="content-modules" tabindex="-1">Content Modules <a class="header-anchor" href="#content-modules" aria-label="Permalink to &quot;Content Modules&quot;">​</a></h3><ul><li><strong>Content View</strong>: Allow viewing assigned content</li><li><strong>Search View</strong>: Enable content search functionality</li><li><strong>Learn Platform</strong>: Access to learning modules</li></ul><h3 id="assistant-features" tabindex="-1">Assistant Features <a class="header-anchor" href="#assistant-features" aria-label="Permalink to &quot;Assistant Features&quot;">​</a></h3><ul><li><strong>Assistant Chat Bot</strong>: Enable AI chatbot interactions</li><li><strong>LaunchPad</strong>: Access to content organization tool</li><li><strong>Assistant Control Panel</strong>: Manage chat sessions and settings</li><li><strong>Assistant Content Selector</strong>: Choose content for interactions</li><li><strong>Assistant AI Settings</strong>: Configure AI-specific chat settings</li><li><strong>Blueprints</strong>: Create and use structured Blueprints</li><li><strong>Chat History</strong>: View and manage previous chat sessions</li></ul><h2 id="user-privileges-needed" tabindex="-1">User Privileges Needed <a class="header-anchor" href="#user-privileges-needed" aria-label="Permalink to &quot;User Privileges Needed&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"><strong>Action</strong></th><th style="text-align:left;"><strong>Privilege Needed</strong></th></tr></thead><tbody><tr><td style="text-align:left;">To access user preferences:</td><td style="text-align:left;">Platform Access Level: Admin</td></tr><tr><td style="text-align:left;">To modify user preferences:</td><td style="text-align:left;">Administrator Access Level: User Management Full Access</td></tr></tbody></table><h2 id="saving-changes" tabindex="-1">Saving Changes <a class="header-anchor" href="#saving-changes" aria-label="Permalink to &quot;Saving Changes&quot;">​</a></h2><ul><li>After configuring preferences, click <strong>Submit</strong> to apply the changes.</li><li>Changes take effect immediately upon saving.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li>Regularly review and update user preferences to ensure optimal platform experience.</li><li>Consider user roles and responsibilities when configuring access levels.</li><li>Communicate preference changes to users to prevent confusion.</li></ul><div class="language-Final vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Final</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span></code></pre></div>',32)]))}const f=a(n,[["render",r]]);export{g as __pageData,f as default};
